Bambu Lab P2S 0.4 nozzle.change_filament_gcode:
;======== P2S filament_change gcode ==========
;===== Based on official 2026/04/08 filament change gcode =====

M620 S[next_extruder]A
M204 S9000
{if toolchange_count > 1 && (z_hop_types[current_extruder] == 0 || z_hop_types[current_extruder] == 3)}
G17
G2 Z{z_after_toolchange + 0.4} I0.86 J0.86 P1 F10000 ; spiral lift a little from second lift
{endif}

;nozzle_change_gcode

G1 Z{max_layer_z + 3.0} F1200

M400
M106 P1 S0

{if toolchange_count == 2}
; get travel path for change filament
;M620.1 X[travel_point_1_x] Y[travel_point_1_y] F21000 P0
;M620.1 X[travel_point_2_x] Y[travel_point_2_y] F21000 P1
;M620.1 X[travel_point_3_x] Y[travel_point_3_y] F21000 P2
{endif}

{if ((filament_type[current_extruder] == "PLA") || (filament_type[current_extruder] == "PLA-CF") || (filament_type[current_extruder] == "PETG")) && (nozzle_diameter[current_extruder] == 0.2)}
M620.10 A0 F74.8347 L[flush_length] H{nozzle_diameter[current_extruder]} T{flush_temperatures[current_extruder]} P{nozzle_temperature[current_extruder]} S1
{else}
M620.10 A0 F{flush_volumetric_speeds[current_extruder]/2.4053*60} L[flush_length] H{nozzle_diameter[current_extruder]} T{flush_temperatures[current_extruder]} P{nozzle_temperature[current_extruder]} S1
{endif}

{if ((filament_type[next_extruder] == "PLA") || (filament_type[next_extruder] == "PLA-CF") || (filament_type[next_extruder] == "PETG")) && (nozzle_diameter[next_extruder] == 0.2)}
M620.10 A1 F74.8347 L[flush_length] H{nozzle_diameter[next_extruder]} T{flush_temperatures[next_extruder]} P{nozzle_temperature[next_extruder]} S1
{else}
M620.10 A1 F{flush_volumetric_speeds[next_extruder]/2.4053*60} L[flush_length] H{nozzle_diameter[next_extruder]} T{flush_temperatures[next_extruder]} P{nozzle_temperature[next_extruder]} S1
{endif}

{if long_retraction_when_cut}
M620.11 P1 L0 I[current_extruder] E-{retraction_distance_when_cut} F{max((flush_volumetric_speeds[current_extruder]/2.4053*60), 200)}
{else}
M620.11 P0 L0 I[current_extruder] E0
{endif}

M620.11 K0 I[current_extruder] R0


T[next_extruder]

;deretract
{if filament_type[next_extruder] == "TPU"}
{else}
{if filament_type[next_extruder] == "PA"}
;VG1 E1 F{max(new_filament_e_feedrate, 200)}
;VG1 E1 F{max(new_filament_e_feedrate/2, 100)}
{else}
;VG1 E4 F{max(new_filament_e_feedrate, 200)}
;VG1 E4 F{max(new_filament_e_feedrate/2, 100)}
{endif}
{endif}

; VFLUSH_START
{if flush_length>41.5}
;VG1 E41.5 F{min(old_filament_e_feedrate,new_filament_e_feedrate)}
;VG1 E{flush_length-41.5} F{new_filament_e_feedrate}
{else}
;VG1 E{flush_length} F{min(old_filament_e_feedrate,new_filament_e_feedrate)}
{endif}
SYNC T{ceil(flush_length / 80) * 5}
; VFLUSH_END

M1002 set_filament_type:{filament_type[next_extruder]}

M400
M83
{if next_extruder < 255}
M620.10 R{retract_length_toolchange[filament_map[next_extruder]-1]}
M628 S0
;VM109 S[new_filament_temp]

M629
M400
M983.3 F{filament_max_volumetric_speed[next_extruder]/2.4} A0.4 R{retract_length_toolchange[filament_map[next_extruder]-1]}
M400

G1 Z{max_layer_z + 3.0} F3000
{if layer_z <= (initial_layer_print_height + 0.001)}
M204 S[initial_layer_acceleration]
{else}
M204 S[travel_acceleration]
{endif}

{else}
G1 X[x_after_toolchange] Y[y_after_toolchange] Z[z_after_toolchange] F12000
{endif}

M621 S[next_extruder]A

M622.1 S0 ;for prev version, default skip
M1002 judge_flag powerloss_resume_flag
M622 J1
M983.3 F{filament_max_volumetric_speed[next_extruder]/2.4} A0.4 R{retract_length_toolchange[filament_map[next_extruder]-1]}
M400
G1 Z{max_layer_z + 3.0} F3000
{if layer_z <= (initial_layer_print_height + 0.001)}
M204 S[initial_layer_acceleration]
{else}
M204 S[travel_acceleration]
{endif}
M1002 set_flag powerloss_resume_flag=0
M623

{if (filament_type[next_extruder] == "PLA") ||  (filament_type[next_extruder] == "PETG")
 ||  (filament_type[next_extruder] == "PLA-CF")  ||  (filament_type[next_extruder] == "PETG-CF")}
M1015.4 S1 K1 H[nozzle_diameter] ;enable E air printing detect
{else}
M1015.4 S0 K0 H[nozzle_diameter] ;disable E air printing detect
{endif}

M620.6 I[next_extruder] W1 ;enable ams air printing detect

G1 Y256 F18000

{if (overall_chamber_temperature < 40)}
{if (layer_num + 1 <= close_fan_the_first_x_layers[next_extruder])}
    {if (min_vitrification_temperature <= 50)}
        M106 P2 S{first_x_layer_fan_speed[next_extruder]*255.0/100.0 };set first x_layer aux fan
    {endif}
{elsif (layer_num + 1 < full_fan_speed_layer[next_extruder] && full_fan_speed_layer[next_extruder] > close_fan_the_first_x_layers[next_extruder])}
    {if (min_vitrification_temperature <= 50)}
        M106 P2 S{(first_x_layer_fan_speed[next_extruder] + (additional_cooling_fan_speed[next_extruder] - first_x_layer_fan_speed[next_extruder]) * (layer_num + 1 - close_fan_the_first_x_layers[next_extruder]) / (full_fan_speed_layer[next_extruder] - close_fan_the_first_x_layers[next_extruder])) * 255.0/100.0}
    {endif}
{else}
    {if (min_vitrification_temperature <= 50)}
        {if (nozzle_diameter == 0.2)}
            M142 P1 R30 S40 U{max_additional_fan/100.0} V1.0 O45; set PLA/TPU ND0.2 chamber autocooling
        {else}
            M142 P1 R30 S40 U{max_additional_fan/100.0} V1.0 O45; set PLA/TPU ND0.4 chamber autocooling
        {endif}
    {endif}
{endif}
{endif}

M622.1 S0
M1002 judge_flag ventobox_replace_aux1_fan_flag
M622 J0
{if (layer_num + 1 <= close_fan_the_first_x_layers[next_extruder])}
    M106 P10 S{first_x_layer_fan_speed[next_extruder]*255.0/100.0 };set first x_layer left aux fan 
{elsif (layer_num + 1 < full_fan_speed_layer[next_extruder] && full_fan_speed_layer[next_extruder] > close_fan_the_first_x_layers[next_extruder])}
    M106 P10 S{(first_x_layer_fan_speed[next_extruder] + (additional_cooling_fan_speed[next_extruder] - first_x_layer_fan_speed[next_extruder]) * (layer_num + 1 - close_fan_the_first_x_layers[next_extruder]) / (full_fan_speed_layer[next_extruder] - close_fan_the_first_x_layers[next_extruder])) * 255.0/100.0}
{else}
    M106 P10 S{additional_cooling_fan_speed[next_extruder]*255.0/100.0};set left aux fan
{endif}
